    adcs_vec3_t n_check_body, n_check_ref;
    adcs_vec3_t mapped_check_ref;
    double dot_prod;
    adcs_status_t triad_status;

    /* 1. Null pointer check */
    if ((body_primary == NULL) || (body_secondary == NULL) ||
        (ref_primary == NULL) || (ref_secondary == NULL) ||
        (check_body == NULL) || (check_ref == NULL) ||
        (c_bi == NULL) || (alignment == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Construct C_BI using primary and secondary pairs */
    triad_status = adcs_triad(body_primary, body_secondary, ref_primary, ref_secondary, c_bi);
    if (triad_status != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return triad_status;
    }

    /* 3. Normalize check_body */
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &n_check_body) != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return ADCS_E_DEGENERATE;
    }

    /* 4. Normalize check_ref */
    if (adcs_vec3_normalize(check_ref, ADCS_EPS_NORM, &n_check_ref) != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return ADCS_E_DEGENERATE;
    }

    /* 5. Map check_ref to body frame: v_b = C_BI * v_i */
    mapped_check_ref = adcs_mat3_mul_vec(c_bi, &n_check_ref);

    /* 6. Calculate dot alignment between normalized check_body and mapped check_ref */
    dot_prod = adcs_vec3_dot(&n_check_body, &mapped_check_ref);

    /* 7. Clamp alignment to [-1, 1] */
    *alignment = ADCS_CLAMP(dot_prod, -1.0, 1.0);

    return ADCS_OK;
}

